import{_ as a,o as n,c as i,a4 as t}from"./chunks/framework.DAe4SYBh.js";const _=JSON.parse('{"title":"fw_printfenv 使用","description":"","frontmatter":{},"headers":[],"relativePath":"goke/v500/fw_printfenv使用.md","filePath":"goke/v500/fw_printfenv使用.md"}'),r={name:"goke/v500/fw_printfenv使用.md"};function o(l,e,s,c,p,d){return n(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="fw-printfenv-使用" tabindex="-1">fw_printfenv 使用 <a class="header-anchor" href="#fw-printfenv-使用" aria-label="Permalink to “fw_printfenv 使用”">​</a></h1><h2 id="一、编译" tabindex="-1">一、编译 <a class="header-anchor" href="#一、编译" aria-label="Permalink to “一、编译”">​</a></h2><p>先编译一遍 SDK</p><p>然后进入 <code>out/xm72020300/boot_builddir</code> 目录</p><p>编译 fw_printfenv 源码 <code>make ARCH=arm CROSS_COMPILE=arm-gcc7.3-linux-musleabi- envtools</code></p><h2 id="二、内核配置" tabindex="-1">二、内核配置 <a class="header-anchor" href="#二、内核配置" aria-label="Permalink to “二、内核配置”">​</a></h2><p>在使用 fw_printfenv 时遇到错误 <code>Error locking file /var/lock/fw_printfenv.lock</code></p><p>内核可能默认不配置 POSIX 标准文件锁定 API，所以程序执行到文件加锁与解锁的 flock() 时失败</p><p>在内核 menuconfig 中搜索 <code>CONFIG_FILE_LOCKING</code>，打卡如下配置，重新编译内核</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[*] Enable POSIX file locking API</span></span>
<span class="line"><span>[*]   Enable Mandatory file locking (NEW)</span></span></code></pre></div><h2 id="三、修改配置文件" tabindex="-1">三、修改配置文件 <a class="header-anchor" href="#三、修改配置文件" aria-label="Permalink to “三、修改配置文件”">​</a></h2><p>fw_env.config 文件用于配置 fw_printfenv 工具指向的环境变量分区。</p><p>以 xm72020300 为例，在 fw_env.config 文件注释掉其他行，新增以下配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># NOR example</span></span>
<span class="line"><span># MTD device name       Device offset   Env. size       Flash sector size       Number of sectors</span></span>
<span class="line"><span>/dev/mtd1               0x0000          0x10000         0x20000                 1</span></span></code></pre></div><ol><li>MTD device name 通过 <code>cat /proc/mtd</code>，确认 bootargs 分区名为 mtd1</li><li>Device offset 为相对于 MTD device name 指定的分区的偏移，因为整个分区是单独的环境变量分区，因此是 0x0000</li><li>Env. size 查看 uboot 源码目录下的 <code>configs/xm72020300_quickstart_defconfig</code> 文件中的宏定义 <code>CONFIG_ENV_SIZE=0x10000</code></li><li>Flash sector 查看 uboot 源码目录下的 <code>include/configs/xm72020300.h</code> 文件中的宏定义 <code>#define CONFIG_ENV_OFFSET 0x20000</code> 和 <code>configs/xm72020300_quickstart_defconfig</code> 文件中的宏定义 <code>CONFIG_ENV_OFFSET=0x20000</code></li><li>Number of sectors 根据实际情况，一般为 1</li></ol><h2 id="四、使用" tabindex="-1">四、使用 <a class="header-anchor" href="#四、使用" aria-label="Permalink to “四、使用”">​</a></h2><p>将编译后的 fw_printfenv 执行程序拷贝到板端，fw_env.config 文件拷贝到板端 <code>/etc</code> 目录下</p><p><strong>必要</strong>，创建 fw_setenv 软链接，<code>ln -s fw_printfenv fw_setenv </code></p><p><code>fw_printfenv -h</code> 查看帮助</p><p><code>fw_printfenv </code> 相当于 printenv，打印环境变量信息</p><p><code>fw_setenv $变量 $值</code> 相当于 setenv+saveenv，设置和保存环境变量信息</p><h2 id="五、通过代码使用" tabindex="-1">五、通过代码使用 <a class="header-anchor" href="#五、通过代码使用" aria-label="Permalink to “五、通过代码使用”">​</a></h2><p>链接 lib.a 库，参考 fw_env_main.c 实现</p><h2 id="六、常见问题" tabindex="-1">六、常见问题 <a class="header-anchor" href="#六、常见问题" aria-label="Permalink to “六、常见问题”">​</a></h2><ol><li>如果内核打开了 POSIX 标准文件锁定 API 配置后仍然遇到 <code>Error locking file /var/lock/fw_printfenv.lock</code> ，检查该目录的文件系统是否为只读</li></ol><h2 id="七、参考链接" tabindex="-1">七、参考链接 <a class="header-anchor" href="#七、参考链接" aria-label="Permalink to “七、参考链接”">​</a></h2><p><a href="https://blog.csdn.net/m0_37383484/article/details/129561114?spm=1001.2101.3001.6650.5&amp;utm_medium=distribute.pc_relevant.none-task-blog-2~default~CTRLIST~Rate-5-129561114-blog-124358700.235%5Ev38%5Epc_relevant_anti_vip_base&amp;depth_1-utm_source=distribute.pc_relevant.none-task-blog-2~default~CTRLIST~Rate-5-129561114-blog-124358700.235%5Ev38%5Epc_relevant_anti_vip_base&amp;utm_relevant_index=8" target="_blank" rel="noreferrer">海思 fw_printenv 和 fw_setenv 工具详解_积步千里的博客-CSDN博客</a></p><p><a href="https://bbs.aw-ol.com/topic/2923/fw_printfenv%E4%B8%8D%E5%8F%AF%E7%94%A8-error-locking-file-var-lock-fw_printenv-lock" target="_blank" rel="noreferrer">fw_printfenv不可用(Error locking file /var/lock/fw_printenv.lock) | 全志在线开发者论坛 (aw-ol.com)</a></p><p><a href="https://blog.csdn.net/xl19862005/article/details/118342662" target="_blank" rel="noreferrer">在linux系统中通过fw_printenv查看和设置u-boot中的环境变量-CSDN博客</a></p>`,29)])])}const h=a(r,[["render",o]]);export{_ as __pageData,h as default};
